sys_ui_page.client_script:
function actionOK() {
    //alert(g_form.getValue('serial_number'));
    //alert(g_form.getValue('assigned'));
    //alert(g_form.getValue('owner'));

    //invoke Ajax
    var ga = new GlideAjax('ClearLaptopOwner'); // HelloWorld is the script include class 
    ga.addParam('sysparm_name', 'clearOwner'); // helloWorld is the script include method 
    ga.addParam('sysparm_sn_number', g_form.getValue('serial_number')); 
    ga.getXML(parseResponse);

    return true;
}

// the callback function for returning the result from the server-side code
function parseResponse(response) {
    var result = JSON.parse(response.responseXML.documentElement.getAttribute("answer"));

    if (result.answer === 'OK') {
		//close the domal
		GlideModal.get().destroy();
    } else {
		//alert the update faulture.
		alert('Update failure! Please contact System Administrator!');
	}

}
